const SEASON_KEY='puckit-season-end-v1';
const SEASON_DURATION=14*24*60*60*1000;
function getSeasonEnd():number{
 let end=Number(localStorage.getItem(SEASON_KEY));
 if(!Number.isFinite(end)||end<=0){end=Date.now()+SEASON_DURATION;localStorage.setItem(SEASON_KEY,String(end));}
 if(Date.now()>=end){const periods=Math.floor((Date.now()-end)/SEASON_DURATION)+1;end+=periods*SEASON_DURATION;localStorage.setItem(SEASON_KEY,String(end));}
 return end;
}
function seasonCountdownText():string{
 const left=Math.max(0,getSeasonEnd()-Date.now());
 const days=Math.floor(left/86400000),hours=Math.floor(left%86400000/3600000),minutes=Math.floor(left%3600000/60000),seconds=Math.floor(left%60000/1000);
 return days+'Д '+[hours,minutes,seconds].map(v=>String(v).padStart(2,'0')).join(':');
}
window.setInterval(()=>{const node=$<HTMLElement>('[data-season-countdown]');if(node)node.textContent=seasonCountdownText();},1000);

const TRELLIS_PROXY='https://little-morning-b296.bratskiymax0.workers.dev';
const HERO_MODEL_DB='puckit-hero-models-v1';
let heroGenerationBusy=false;
const TRELLIS_SESSION=typeof crypto!=='undefined'&&'randomUUID'in crypto?crypto.randomUUID():'puckit-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
function openHeroModelDb():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const request=indexedDB.open(HERO_MODEL_DB,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('models'))request.result.createObjectStore('models');};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('Не удалось открыть хранилище модели.'));});}
async function getSavedHeroModel():Promise<Blob|null>{const db=await openHeroModelDb();return new Promise((resolve,reject)=>{const request=db.transaction('models','readonly').objectStore('models').get('base');request.onsuccess=()=>{db.close();resolve(request.result instanceof Blob?request.result:null);};request.onerror=()=>{db.close();reject(request.error||new Error('Не удалось прочитать модель.'));};});}
async function saveHeroModel(blob:Blob):Promise<void>{const db=await openHeroModelDb();return new Promise((resolve,reject)=>{const tx=db.transaction('models','readwrite');tx.objectStore('models').put(blob,'base');tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error||new Error('Не удалось сохранить модель.'));};});}
async function callTrellis(api:string,data:unknown[]):Promise<any[]>{const start=await fetch(TRELLIS_PROXY+'/gradio_api/call/'+api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data,session_hash:TRELLIS_SESSION})});if(!start.ok)throw new Error('TRELLIS '+api+': HTTP '+start.status+' · '+(await start.text()).slice(0,240));const startData=await start.json() as {event_id?:string};if(!startData.event_id)throw new Error('TRELLIS не вернул event_id для '+api);const streamUrl=TRELLIS_PROXY+'/gradio_api/call/'+api+'/'+encodeURIComponent(startData.event_id)+'?session_hash='+encodeURIComponent(TRELLIS_SESSION);const response=await fetch(streamUrl,{headers:{'Accept':'text/event-stream'}});if(!response.ok)throw new Error('Ожидание '+api+': HTTP '+response.status+' · '+(await response.text()).slice(0,240));if(!response.body)throw new Error('TRELLIS не открыл поток очереди '+api);const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';try{while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});const blocks=buffer.split(/\r?\n\r?\n/);buffer=blocks.pop()||'';for(const block of blocks){for(const line of block.split(/\r?\n/)){if(!line.startsWith('data:'))continue;let message:any;try{message=JSON.parse(line.slice(5).trim());}catch{continue;}if(message?.event_id!==startData.event_id)continue;if(message.msg==='process_completed'||message.event==='complete'){await reader.cancel();const result=message.output?.data??message.data??message.output?.result??message.result;if(Array.isArray(result))return result;throw new Error('TRELLIS '+api+' завершил запрос без массива результатов: '+JSON.stringify(message).slice(0,1800));}if(message.msg==='unexpected_error'||message.msg==='server_stopped')throw new Error(String(message.error||message.message||'Ошибка очереди TRELLIS'));if(message.msg==='queue_full')throw new Error('Очередь TRELLIS переполнена. Попробуй ещё раз чуть позже.');}}}}finally{try{reader.releaseLock();}catch{}}throw new Error('Поток TRELLIS завершился без результата '+api+'.');}
function fileDataPath(value:any):string|null{if(typeof value==='string')return value;if(value&&typeof value.path==='string')return value.path;if(value&&typeof value.url==='string')return value.url;if(value&&value.file&&typeof value.file.path==='string')return value.file.path;return null;}
async function generateHeroModel(file:File){if(heroGenerationBusy)return;heroGenerationBusy=true;const status=$<HTMLElement>('#hero-model-status'),button=$<HTMLButtonElement>('[data-action="pick-hero-model"]');const setStatus=(message:string)=>{if(status)status.textContent=message;};if(button)button.disabled=true;try{setStatus('1/4 · Загружаем референс на сервер…');const form=new FormData();form.append('files',file,file.name);const upload=await fetch(TRELLIS_PROXY+'/gradio_api/upload',{method:'POST',body:form});if(!upload.ok)throw new Error('Загрузка изображения: HTTP '+upload.status+' · '+(await upload.text()).slice(0,240));const uploaded=await upload.json() as string[];if(!Array.isArray(uploaded)||!uploaded[0])throw new Error('Hugging Face не вернул путь загруженного изображения.');const imageInput={path:uploaded[0],meta:{_type:'gradio.FileData'}};setStatus('2/4 · Готовим параметры генерации…');/* start_session не нужен: extract_glb сам создаёт каталог сессии перед сохранением GLB. *//* preprocess_image исключён: он вызывает внешний BRIA background-removal сервис, который сейчас отвечает 404. TRELLIS принимает исходное изображение напрямую. */const seedResult=await callTrellis('get_seed',[true,0]);const seed=seedResult?.[0]??0;setStatus('3/4 · TRELLIS строит 3D-геометрию. Это займёт несколько минут…');const generated=await callTrellis('image_to_3d',[imageInput,seed,'1024',7.5,.7,12,5,7.5,.5,12,3,1,0,12,3]);const state=generated?.[0]??null;/* Gradio State is stored server-side per session_hash and is intentionally serialized as null in API output. extract_glb resolves it from the same TRELLIS_SESSION. */if(!Array.isArray(generated)||generated.length<2)throw new Error('TRELLIS не вернул ожидаемый ответ image_to_3d. Ответ: '+JSON.stringify(generated).slice(0,900));setStatus('4/4 · Запекаем материалы и собираем GLB…');const extracted=await callTrellis('extract_glb',[state,300000,2048]);const path=fileDataPath(extracted?.[1])||fileDataPath(extracted?.[0]);if(!path)throw new Error('TRELLIS не вернул путь к GLB-файлу. Ответ extract_glb: '+JSON.stringify(extracted).slice(0,1800));let fileUrl:string;if(path.startsWith('http')){const parsed=new URL(path);fileUrl=TRELLIS_PROXY+parsed.pathname+parsed.search;}else if(path.startsWith('/gradio_api/file=')){fileUrl=TRELLIS_PROXY+path;}else{fileUrl=TRELLIS_PROXY+'/gradio_api/file='+encodeURIComponent(path);}const modelResponse=await fetch(fileUrl);if(!modelResponse.ok)throw new Error('Не удалось скачать GLB: HTTP '+modelResponse.status+' · '+(await modelResponse.text()).slice(0,240));const blob=await modelResponse.blob();if(blob.size<1000)throw new Error('Полученный GLB слишком маленький или пустой.');setStatus('4/4 · Сохраняем модель в игре…');await saveHeroModel(new Blob([blob],{type:'model/gltf-binary'}));const stage=hero3DStage;if(stage){const objectUrl=URL.createObjectURL(blob);try{await stage.loadBaseModel(objectUrl);}finally{URL.revokeObjectURL(objectUrl);}}setStatus('ГОТОВО! 3D-модель сохранена на этом устройстве.');}catch(error){setStatus('Ошибка: '+(error instanceof Error?error.message:String(error)));}finally{heroGenerationBusy=false;if(button)button.disabled=false;}}

let hero3DStage:Hero3DStage|null=null;
