const makeHero=(role:HeroRole,name:string):HeroProfile=>({role,name:name.trim()||'Новичок',level:1,xp:0,skillPoints:5,stats:role==='G'?{speed:48,agility:66,strength:70,stamina:68,reaction:76}:{speed:role==='LD'||role==='RD'?64:72,agility:role==='C'?76:69,strength:role==='LD'||role==='RD'?74:62,stamina:70,reaction:42},gear:heroGearSlots(role).map((x,i)=>i===0?'Стартовый комплект':i===3?(role==='G'?'Клюшка вратаря «Старт»':'Клюшка «Старт»'):'Базовый комплект'),trophies:[]});
const load=():Team=>{try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw) as Team;if(saved.rosterVersion!==3){const migrated=autoFillRoster(saved);localStorage.setItem(KEY,JSON.stringify(migrated));return migrated;}return saved;}}catch{}return createTeam();};
