function header(t:string,back=true){const nextXp=hero?100+(hero.level-1)*50:100;const progress=hero?Math.max(0,Math.min(100,hero.xp/nextXp*100)):0;const avatar=hero?'<button class="crest hero-header-avatar" data-screen="heroRoom" aria-label="Открыть профиль игрока"><svg viewBox="0 0 48 48" aria-hidden="true"><defs><linearGradient id="playerAvatarBg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#75e5cf"/><stop offset="1" stop-color="#176b78"/></linearGradient><linearGradient id="playerHelmet" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f5fbff"/><stop offset="1" stop-color="#8db8c9"/></linearGradient></defs><circle cx="24" cy="24" r="23" fill="url(#playerAvatarBg)"/><path d="M7 47Q9 32 24 31Q39 32 41 47" fill="#102d3b"/><path d="M14 22Q12 8 24 7Q37 8 35 23L32 31H16Z" fill="url(#playerHelmet)" stroke="#e8fbff" stroke-width="1.2"/><path d="M13 19Q13 5 24 5Q36 5 36 19L31 17H17Z" fill="#17374a"/><path d="M15 20H33L31 26H17Z" fill="#0d2738" stroke="#8ee7e0" stroke-width="1.5"/><path d="M17 21L31 21M18 24L30 24" stroke="#d8faff" stroke-width="1.2"/><path d="M20 28L24 30L28 28" fill="none" stroke="#17374a" stroke-width="1.5"/></svg><small>LVL '+hero.level+'</small></button>':'<div class="crest">🏒</div>';const meta=hero&&!back?'<div class="hero-header-progress"><div class="hero-header-xp"><span>УРОВЕНЬ '+hero.level+'</span><b>'+hero.xp+' / '+nextXp+' XP</b></div><div class="hero-header-track"><i style="width:'+progress.toFixed(1)+'%"></i></div></div>':'';return '<header class="top"><div class="brand">'+(back?'<button class="back" data-action="back">←</button>':'')+avatar+'<div class="hero-header-copy"><div class="eyebrow">'+(hero&&!back?'PLAYER PROFILE':'HOCKEY: PUCK IT!')+'</div><h1>'+esc(t)+'</h1>'+meta+'</div></div><span class="live">WEB PLAYTEST</span></header>';}
